import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { useToast } from "@/hooks/use-toast";
import { CheckSquare, X, Check, Clock } from "lucide-react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatDateShort, getTripDuration } from "@/lib/date-utils";
import { getStatusColor, statusLabels } from "@/lib/status-utils";
import type { TripWithDetails, User, TripStatus } from "@shared/schema";

export default function Approvals() {
  const [statusFilter, setStatusFilter] = useState<string>("pending");
  const [approvalDialog, setApprovalDialog] = useState<{
    open: boolean;
    type: "approve" | "reject" | null;
    tripId: string | null;
  }>({ open: false, type: null, tripId: null });
  const [comment, setComment] = useState("");
  const { toast } = useToast();

  const { data: users = [] } = useQuery<User[]>({
    queryKey: ["/api/users"],
  });

  // Используем первого территориального менеджера (в реальности из auth)
  const currentUser = users.find(u => u.role === "territorial_manager") || users[0];

  const { data: trips = [], isLoading } = useQuery<TripWithDetails[]>({
    queryKey: ["/api/trips"],
    enabled: !!currentUser,
  });

  // Фильтруем командировки подчиненных
  const subordinateTrips = trips.filter(trip => 
    trip.employee.managerId === currentUser?.id
  );

  const approveMutation = useMutation({
    mutationFn: ({ tripId, status, comment }: { tripId: string; status: TripStatus; comment?: string }) => 
      apiRequest("POST", `/api/approvals/${tripId}`, {
        approverId: currentUser?.id,
        status,
        comment,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/trips"] });
      setApprovalDialog({ open: false, type: null, tripId: null });
      setComment("");
      toast({
        title: "Успешно",
        description: "Решение по командировке принято",
      });
    },
    onError: () => {
      toast({
        title: "Ошибка",
        description: "Не удалось обработать заявку",
        variant: "destructive",
      });
    },
  });

  const handleApprove = (tripId: string) => {
    setApprovalDialog({ open: true, type: "approve", tripId });
  };

  const handleReject = (tripId: string) => {
    setApprovalDialog({ open: true, type: "reject", tripId });
  };

  const handleSubmitApproval = () => {
    if (!approvalDialog.tripId) return;
    if (approvalDialog.type === "reject" && !comment.trim()) {
      toast({
        title: "Ошибка",
        description: "Укажите причину отклонения",
        variant: "destructive",
      });
      return;
    }

    approveMutation.mutate({
      tripId: approvalDialog.tripId,
      status: approvalDialog.type === "approve" ? "approved" : "rejected",
      comment: comment.trim() || undefined,
    });
  };

  const filteredTrips = subordinateTrips.filter(trip => {
    if (statusFilter === "all") return true;
    return trip.status === statusFilter;
  });

  const pendingCount = subordinateTrips.filter(t => t.status === "pending").length;
  const approvedCount = subordinateTrips.filter(t => t.status === "approved").length;
  const rejectedCount = subordinateTrips.filter(t => t.status === "rejected").length;

  return (
    <div className="flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold text-foreground">Согласование</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Командировки подчиненных, требующие вашего согласования
          </p>
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">
              Ожидают решения
            </CardTitle>
            <Clock className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-semibold">{pendingCount}</div>
            <p className="text-xs text-muted-foreground mt-1">
              Новых заявок
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">
              Утверждено
            </CardTitle>
            <Check className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-semibold">{approvedCount}</div>
            <p className="text-xs text-muted-foreground mt-1">
              Всего
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">
              Отклонено
            </CardTitle>
            <X className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-semibold">{rejectedCount}</div>
            <p className="text-xs text-muted-foreground mt-1">
              Всего
            </p>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-4">
            <div>
              <CardTitle>Очередь согласования</CardTitle>
              <CardDescription>Заявки на командировки от подчиненных</CardDescription>
            </div>
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-48" data-testid="select-approval-filter">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="pending">На согласовании</SelectItem>
                <SelectItem value="approved">Утвержденные</SelectItem>
                <SelectItem value="rejected">Отклоненные</SelectItem>
                <SelectItem value="all">Все</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="space-y-2">
              {[...Array(3)].map((_, i) => (
                <Skeleton key={i} className="h-20 w-full" />
              ))}
            </div>
          ) : filteredTrips.length === 0 ? (
            <div className="flex items-center justify-center py-16 text-muted-foreground">
              <div className="text-center">
                <CheckSquare className="h-12 w-12 mx-auto mb-3 opacity-20" />
                <p className="text-sm">
                  {statusFilter === "pending" ? "Заявок на согласование нет" : "Командировок не найдено"}
                </p>
                <p className="text-xs mt-1">
                  {statusFilter === "pending" && "Здесь появятся заявки от подчиненных"}
                </p>
              </div>
            </div>
          ) : (
            <Accordion type="single" collapsible className="w-full">
              {filteredTrips.map((trip) => (
                <AccordionItem key={trip.id} value={trip.id} className="border rounded-md px-4 mb-2">
                  <AccordionTrigger className="hover:no-underline">
                    <div className="flex items-center justify-between w-full mr-4">
                      <div className="flex items-center gap-4">
                        <div className="text-left">
                          <div className="flex items-center gap-2 mb-1">
                            <span className="font-medium">{trip.employee.fullName}</span>
                            <Badge variant="secondary" className={getStatusColor(trip.status)}>
                              {statusLabels[trip.status]}
                            </Badge>
                          </div>
                          <p className="text-sm text-muted-foreground">
                            {trip.city.name} • {formatDateShort(trip.startDate)} - {formatDateShort(trip.endDate)} • {getTripDuration(trip.startDate, trip.endDate)} дн.
                          </p>
                        </div>
                      </div>
                    </div>
                  </AccordionTrigger>
                  <AccordionContent>
                    <div className="space-y-4 pt-4">
                      <div>
                        <h4 className="text-sm font-medium mb-1">Цель командировки:</h4>
                        <p className="text-sm text-muted-foreground">{trip.purpose}</p>
                      </div>

                      {trip.status === "pending" && (
                        <div className="flex gap-2 pt-2">
                          <Button
                            onClick={() => handleApprove(trip.id)}
                            disabled={approveMutation.isPending}
                            data-testid={`button-approve-${trip.id}`}
                          >
                            <Check className="h-4 w-4 mr-2" />
                            Утвердить
                          </Button>
                          <Button
                            variant="destructive"
                            onClick={() => handleReject(trip.id)}
                            disabled={approveMutation.isPending}
                            data-testid={`button-reject-${trip.id}`}
                          >
                            <X className="h-4 w-4 mr-2" />
                            Отклонить
                          </Button>
                        </div>
                      )}

                      {trip.approvals && trip.approvals.length > 0 && (
                        <div className="border-t pt-4">
                          <h4 className="text-sm font-medium mb-2">История согласования:</h4>
                          {trip.approvals.map((approval) => (
                            <div key={approval.id} className="text-sm text-muted-foreground">
                              <Badge variant="secondary" className={getStatusColor(approval.status)}>
                                {statusLabels[approval.status]}
                              </Badge>
                              {approval.comment && (
                                <p className="mt-1 text-xs">Комментарий: {approval.comment}</p>
                              )}
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          )}
        </CardContent>
      </Card>

      <Dialog open={approvalDialog.open} onOpenChange={(open) => {
        setApprovalDialog({ ...approvalDialog, open });
        if (!open) setComment("");
      }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {approvalDialog.type === "approve" ? "Утвердить командировку" : "Отклонить командировку"}
            </DialogTitle>
            <DialogDescription>
              {approvalDialog.type === "approve" 
                ? "Добавьте комментарий к утверждению (необязательно)"
                : "Укажите причину отклонения"}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="approval-comment">
                Комментарий {approvalDialog.type === "reject" && "*"}
              </Label>
              <Textarea
                id="approval-comment"
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder={approvalDialog.type === "approve" 
                  ? "Ваш комментарий..." 
                  : "Укажите причину отклонения..."}
                rows={4}
                data-testid="input-approval-comment"
              />
            </div>
          </div>
          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => {
                setApprovalDialog({ open: false, type: null, tripId: null });
                setComment("");
              }}
            >
              Отмена
            </Button>
            <Button 
              variant={approvalDialog.type === "approve" ? "default" : "destructive"}
              onClick={handleSubmitApproval}
              disabled={approveMutation.isPending}
              data-testid={`button-confirm-${approvalDialog.type}`}
            >
              {approveMutation.isPending ? "Обработка..." : (
                approvalDialog.type === "approve" ? (
                  <>
                    <Check className="h-4 w-4 mr-2" />
                    Утвердить
                  </>
                ) : (
                  <>
                    <X className="h-4 w-4 mr-2" />
                    Отклонить
                  </>
                )
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

