import { sql } from "drizzle-orm";
import { pgTable, text, varchar, timestamp, date } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// Роли пользователей
export type UserRole = 
  | "medical_rep" // Медицинский представитель (МП)
  | "territorial_manager" // Территориальный менеджер (ТМ)
  | "commercial_manager" // Менеджер коммерческого отдела
  | "marketing_director" // Директор отдела маркетинга
  | "sales_director" // Директор отдела продаж
  | "commerce_director"; // Директор отдела коммерции

// Статусы командировки
export type TripStatus = "draft" | "pending" | "approved" | "rejected";

// Пользователи/Сотрудники
export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  fullName: text("full_name").notNull(),
  email: text("email").notNull().unique(),
  role: text("role").notNull().$type<UserRole>(),
  managerId: varchar("manager_id"), // ID руководителя
  department: text("department"), // Отдел
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

// Города
export const cities = pgTable("cities", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: text("name").notNull().unique(),
  region: text("region"), // Регион
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

// Командировки
export const trips = pgTable("trips", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  employeeId: varchar("employee_id").notNull(),
  cityId: varchar("city_id").notNull(),
  startDate: date("start_date").notNull(),
  endDate: date("end_date").notNull(),
  purpose: text("purpose").notNull(), // Цель командировки
  status: text("status").notNull().$type<TripStatus>().default("draft"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

// Согласования
export const approvals = pgTable("approvals", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  tripId: varchar("trip_id").notNull(),
  approverId: varchar("approver_id").notNull(),
  status: text("status").notNull().$type<TripStatus>(),
  comment: text("comment"), // Комментарий при согласовании/отклонении
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

// Insert Schemas
export const insertUserSchema = createInsertSchema(users).omit({
  id: true,
  createdAt: true,
});

export const insertCitySchema = createInsertSchema(cities).omit({
  id: true,
  createdAt: true,
});

export const insertTripSchema = createInsertSchema(trips).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
}).extend({
  startDate: z.string(),
  endDate: z.string(),
});

export const insertApprovalSchema = createInsertSchema(approvals).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// Types
export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;

export type InsertCity = z.infer<typeof insertCitySchema>;
export type City = typeof cities.$inferSelect;

export type InsertTrip = z.infer<typeof insertTripSchema>;
export type Trip = typeof trips.$inferSelect;

export type InsertApproval = z.infer<typeof insertApprovalSchema>;
export type Approval = typeof approvals.$inferSelect;

// Extended types для отображения
export type TripWithDetails = Trip & {
  employee: User;
  city: City;
  approvals?: Approval[];
};

export type UserWithManager = User & {
  manager?: User;
};

