import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Building2 } from "lucide-react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameMonth, isToday, startOfWeek, endOfWeek, isSameDay, parseISO } from "date-fns";
import { ru } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { getStatusColor } from "@/lib/status-utils";
import type { TripWithDetails, User } from "@shared/schema";

export default function CalendarView() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [view, setView] = useState<"month" | "week">("month");
  const [employeeFilter, setEmployeeFilter] = useState<string>("all");

  const { data: trips = [], isLoading } = useQuery<TripWithDetails[]>({
    queryKey: ["/api/trips"],
  });

  const { data: employees = [] } = useQuery<User[]>({
    queryKey: ["/api/users"],
  });

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(currentDate);
  const calendarStart = startOfWeek(monthStart, { locale: ru });
  const calendarEnd = endOfWeek(monthEnd, { locale: ru });
  const days = eachDayOfInterval({ start: calendarStart, end: calendarEnd });

  const weekDays = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];

  const goToPreviousMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1));
  };

  const goToNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1));
  };

  const goToToday = () => {
    setCurrentDate(new Date());
  };

  const getTripsForDate = (date: Date) => {
    const dateStr = format(date, "yyyy-MM-dd");
    return trips.filter(trip => {
      const matchesEmployee = employeeFilter === "all" || trip.employeeId === employeeFilter;
      const isInRange = dateStr >= trip.startDate && dateStr <= trip.endDate;
      return matchesEmployee && isInRange;
    });
  };

  const getStatusIndicatorColor = (status: string) => {
    const colors: Record<string, string> = {
      draft: "bg-muted",
      pending: "bg-amber-500",
      approved: "bg-green-500",
      rejected: "bg-red-500",
    };
    return colors[status] || "bg-muted";
  };

  return (
    <div className="flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold text-foreground">Календарь</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Календарное представление командировок
          </p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="icon"
                onClick={goToPreviousMonth}
                data-testid="button-prev-month"
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>
              <Button
                variant="outline"
                onClick={goToToday}
                data-testid="button-today"
              >
                Сегодня
              </Button>
              <Button
                variant="outline"
                size="icon"
                onClick={goToNextMonth}
                data-testid="button-next-month"
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
              <h2 className="text-lg font-semibold ml-2 capitalize">
                {format(currentDate, "LLLL yyyy", { locale: ru })}
              </h2>
            </div>
            <div className="flex items-center gap-2">
              <Select value={view} onValueChange={(v) => setView(v as "month" | "week")}>
                <SelectTrigger className="w-32" data-testid="select-calendar-view">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="month">Месяц</SelectItem>
                  <SelectItem value="week">Неделя</SelectItem>
                </SelectContent>
              </Select>
              <Select value={employeeFilter} onValueChange={setEmployeeFilter}>
                <SelectTrigger className="w-48" data-testid="select-employee-filter">
                  <SelectValue placeholder="Все сотрудники" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Все сотрудники</SelectItem>
                  {employees.map((emp) => (
                    <SelectItem key={emp.id} value={emp.id}>
                      {emp.fullName}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <Skeleton className="h-96 w-full" />
          ) : (
            <div className="grid grid-cols-7 gap-px bg-border rounded-md overflow-hidden">
              {weekDays.map((day) => (
                <div
                  key={day}
                  className="bg-muted p-2 text-center text-xs font-medium text-muted-foreground"
                >
                  {day}
                </div>
              ))}
              {days.map((day, idx) => {
                const dayTrips = getTripsForDate(day);
                return (
                  <div
                    key={idx}
                    className={cn(
                      "bg-card min-h-24 p-2",
                      !isSameMonth(day, currentDate) && "bg-muted/30",
                      isToday(day) && "bg-primary/5 ring-1 ring-primary/20"
                    )}
                  >
                    <div className={cn(
                      "text-sm font-medium mb-1",
                      !isSameMonth(day, currentDate) && "text-muted-foreground",
                      isToday(day) && "text-primary font-semibold"
                    )}>
                      {format(day, "d")}
                    </div>
                    <div className="space-y-1">
                      {dayTrips.slice(0, 3).map((trip) => (
                        <div
                          key={trip.id}
                          className={cn(
                            "text-xs px-1.5 py-0.5 rounded truncate",
                            getStatusColor(trip.status)
                          )}
                        >
                          {trip.employee.fullName.split(' ')[0]} - {trip.city.name}
                        </div>
                      ))}
                      {dayTrips.length > 3 && (
                        <div className="text-xs text-muted-foreground px-1">
                          +{dayTrips.length - 3} ещё
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {!isLoading && trips.length === 0 && (
            <div className="mt-6 flex items-center justify-center text-muted-foreground">
              <div className="text-center">
                <Building2 className="h-12 w-12 mx-auto mb-3 opacity-20" />
                <p className="text-sm">Командировок в этом месяце нет</p>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Легенда</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-4">
            <div className="flex items-center gap-2">
              <div className="h-3 w-3 rounded-sm bg-amber-500"></div>
              <span className="text-sm">На согласовании</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="h-3 w-3 rounded-sm bg-green-500"></div>
              <span className="text-sm">Утверждено</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="h-3 w-3 rounded-sm bg-red-500"></div>
              <span className="text-sm">Отклонено</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="h-3 w-3 rounded-sm bg-muted"></div>
              <span className="text-sm">Черновик</span>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

