                <main className="flex-1 overflow-auto">
                  <div className="p-8">
                    <Router />
                  </div>
                </main>
              </div>
            </div>
          </SidebarProvider>
          <Toaster />
        </TooltipProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

export default App;

server/storage.ts.content:
import { 
  type User, 
  type InsertUser,
  type City,
  type InsertCity,
  type Trip,
  type InsertTrip,
  type Approval,
  type InsertApproval,
  type TripWithDetails,
  type UserWithManager,
  type TripStatus
} from "@shared/schema";
import { randomUUID } from "crypto";

export interface IStorage {
  // Users
  getUser(id: string): Promise<User | undefined>;
  getUserByEmail(email: string): Promise<User | undefined>;
  getAllUsers(): Promise<User[]>;
  getUsersByRole(role: string): Promise<User[]>;
  getUsersByManager(managerId: string): Promise<User[]>;
  createUser(user: InsertUser): Promise<User>;
  updateUser(id: string, user: Partial<InsertUser>): Promise<User | undefined>;
  deleteUser(id: string): Promise<boolean>;

  // Cities
  getCity(id: string): Promise<City | undefined>;
  getAllCities(): Promise<City[]>;
  getCityByName(name: string): Promise<City | undefined>;
  createCity(city: InsertCity): Promise<City>;
  updateCity(id: string, city: Partial<InsertCity>): Promise<City | undefined>;
  deleteCity(id: string): Promise<boolean>;

  // Trips
  getTrip(id: string): Promise<Trip | undefined>;
  getTripWithDetails(id: string): Promise<TripWithDetails | undefined>;
  getAllTrips(): Promise<Trip[]>;
  getTripsByEmployee(employeeId: string): Promise<Trip[]>;
  getTripsByStatus(status: TripStatus): Promise<Trip[]>;
  getTripsByCity(cityId: string): Promise<Trip[]>;
  getTripsByDateRange(startDate: string, endDate: string): Promise<Trip[]>;
  getTripsForApproval(managerId: string): Promise<TripWithDetails[]>;
  createTrip(trip: InsertTrip): Promise<Trip>;
  updateTrip(id: string, trip: Partial<InsertTrip>): Promise<Trip | undefined>;
  deleteTrip(id: string): Promise<boolean>;

  // Approvals
  getApproval(id: string): Promise<Approval | undefined>;
  getApprovalsByTrip(tripId: string): Promise<Approval[]>;
  getApprovalsByApprover(approverId: string): Promise<Approval[]>;
  createApproval(approval: InsertApproval): Promise<Approval>;
  updateApproval(id: string, approval: Partial<InsertApproval>): Promise<Approval | undefined>;
}

export class MemStorage implements IStorage {
  private users: Map<string, User>;
  private cities: Map<string, City>;
  private trips: Map<string, Trip>;
  private approvals: Map<string, Approval>;

  constructor() {
    this.users = new Map();
    this.cities = new Map();
    this.trips = new Map();
    this.approvals = new Map();
    this.initializeSampleData();
  }

  private initializeSampleData() {
    // Создаем тестовых пользователей
    const director = this.createUserSync({
      fullName: "Сергей Иванов",
      email: "ivanov@company.ru",
      role: "commerce_director",
      department: "Коммерческий отдел",
    });

    const manager = this.createUserSync({
      fullName: "Анна Петрова",
      email: "petrova@company.ru",
      role: "territorial_manager",
      managerId: director.id,
      department: "Отдел продаж",
    });

    this.createUserSync({
      fullName: "Иван Сидоров",
      email: "sidorov@company.ru",
      role: "medical_rep",
      managerId: manager.id,
      department: "Отдел продаж",
    });

    // Создаем города
    this.createCitySync({ name: "Москва", region: "Московская область" });
    this.createCitySync({ name: "Санкт-Петербург", region: "Ленинградская область" });
    this.createCitySync({ name: "Казань", region: "Республика Татарстан" });
    this.createCitySync({ name: "Новосибирск", region: "Новосибирская область" });
  }

  private createUserSync(insertUser: InsertUser): User {
    const id = randomUUID();
    const user: User = { ...insertUser, id, createdAt: new Date() };
    this.users.set(id, user);
    return user;
  }

  private createCitySync(insertCity: InsertCity): City {
    const id = randomUUID();
    const city: City = { ...insertCity, id, createdAt: new Date() };
    this.cities.set(id, city);
    return city;
  }

  // Users
  async getUser(id: string): Promise<User | undefined> {
    return this.users.get(id);
  }

  async getUserByEmail(email: string): Promise<User | undefined> {
    return Array.from(this.users.values()).find(user => user.email === email);
  }

  async getAllUsers(): Promise<User[]> {
    return Array.from(this.users.values());
  }

  async getUsersByRole(role: string): Promise<User[]> {
    return Array.from(this.users.values()).filter(user => user.role === role);
  }

  async getUsersByManager(managerId: string): Promise<User[]> {
    return Array.from(this.users.values()).filter(user => user.managerId === managerId);
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const id = randomUUID();
    const user: User = { ...insertUser, id, createdAt: new Date() };
    this.users.set(id, user);
    return user;
  }

  async updateUser(id: string, updates: Partial<InsertUser>): Promise<User | undefined> {
    const user = this.users.get(id);
    if (!user) return undefined;
    const updated = { ...user, ...updates };
    this.users.set(id, updated);
    return updated;
  }

  async deleteUser(id: string): Promise<boolean> {
    return this.users.delete(id);
  }

  // Cities
  async getCity(id: string): Promise<City | undefined> {
    return this.cities.get(id);
  }

  async getAllCities(): Promise<City[]> {
    return Array.from(this.cities.values());
  }

  async getCityByName(name: string): Promise<City | undefined> {
    return Array.from(this.cities.values()).find(city => city.name.toLowerCase() === name.toLowerCase());
  }

  async createCity(insertCity: InsertCity): Promise<City> {
    const id = randomUUID();
    const city: City = { ...insertCity, id, createdAt: new Date() };
    this.cities.set(id, city);
    return city;
  }

  async updateCity(id: string, updates: Partial<InsertCity>): Promise<City | undefined> {
    const city = this.cities.get(id);
    if (!city) return undefined;
    const updated = { ...city, ...updates };
    this.cities.set(id, updated);
    return updated;
  }

  async deleteCity(id: string): Promise<boolean> {
    return this.cities.delete(id);
  }

  // Trips
  async getTrip(id: string): Promise<Trip | undefined> {
    return this.trips.get(id);
  }

  async getTripWithDetails(id: string): Promise<TripWithDetails | undefined> {
    const trip = this.trips.get(id);
    if (!trip) return undefined;

    const employee = await this.getUser(trip.employeeId);
    const city = await this.getCity(trip.cityId);
    const approvals = await this.getApprovalsByTrip(trip.id);

    if (!employee || !city) return undefined;

    return {
      ...trip,
      employee,
      city,
      approvals,
    };
  }

  async getAllTrips(): Promise<Trip[]> {
    return Array.from(this.trips.values());
  }

  async getTripsByEmployee(employeeId: string): Promise<Trip[]> {
    return Array.from(this.trips.values()).filter(trip => trip.employeeId === employeeId);
  }

  async getTripsByStatus(status: TripStatus): Promise<Trip[]> {
    return Array.from(this.trips.values()).filter(trip => trip.status === status);
  }

  async getTripsByCity(cityId: string): Promise<Trip[]> {
    return Array.from(this.trips.values()).filter(trip => trip.cityId === cityId);
  }

  async getTripsByDateRange(startDate: string, endDate: string): Promise<Trip[]> {
    return Array.from(this.trips.values()).filter(trip => {
      return trip.startDate >= startDate && trip.endDate <= endDate;
    });
  }

  async getTripsForApproval(managerId: string): Promise<TripWithDetails[]> {
    const subordinates = await this.getUsersByManager(managerId);
    const subordinateIds = new Set(subordinates.map(s => s.id));

    const tripsForApproval: TripWithDetails[] = [];

    for (const trip of this.trips.values()) {
      if (trip.status === "pending" && subordinateIds.has(trip.employeeId)) {
        const details = await this.getTripWithDetails(trip.id);
        if (details) {
          tripsForApproval.push(details);
        }
      }
    }

    return tripsForApproval;
  }

  async createTrip(insertTrip: InsertTrip): Promise<Trip> {
    const id = randomUUID();
    const now = new Date();
    const trip: Trip = { 
      ...insertTrip, 
      id, 
      createdAt: now, 
      updatedAt: now 
    };
    this.trips.set(id, trip);
    return trip;
  }

  async updateTrip(id: string, updates: Partial<InsertTrip>): Promise<Trip | undefined> {
    const trip = this.trips.get(id);
    if (!trip) return undefined;
    const updated = { ...trip, ...updates, updatedAt: new Date() };
    this.trips.set(id, updated);
    return updated;
  }

  async deleteTrip(id: string): Promise<boolean> {
    return this.trips.delete(id);
  }

  // Approvals
  async getApproval(id: string): Promise<Approval | undefined> {
    return this.approvals.get(id);
  }

  async getApprovalsByTrip(tripId: string): Promise<Approval[]> {
    return Array.from(this.approvals.values()).filter(approval => approval.tripId === tripId);
  }

  async getApprovalsByApprover(approverId: string): Promise<Approval[]> {
    return Array.from(this.approvals.values()).filter(approval => approval.approverId === approverId);
  }

  async createApproval(insertApproval: InsertApproval): Promise<Approval> {
    const id = randomUUID();
    const now = new Date();
    const approval: Approval = { 
      ...insertApproval, 
      id, 
      createdAt: now, 
      updatedAt: now 
    };
    this.approvals.set(id, approval);
    return approval;
  }

  async updateApproval(id: string, updates: Partial<InsertApproval>): Promise<Approval | undefined> {
    const approval = this.approvals.get(id);
    if (!approval) return undefined;
    const updated = { ...approval, ...updates, updatedAt: new Date() };
    this.approvals.set(id, updated);
    return updated;
  }
}

export const storage = new MemStorage();

